//! PSE molecule-extraction verified against a REAL PyMOL `.pse` fixture
//! (`tests/fixtures/mol3.pse`), generated by PyMOL 3 from a known 3-atom
//! structure. This is the genuine oracle — actual PyMOL output, not a synthetic
//! guess — so it validates the version-specific ChemPy traversal.

use std::path::PathBuf;

use cuemol_importers::PseFileReader;

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

#[test]
fn extracts_the_known_molecule_from_a_real_pse() {
    let mut reader = PseFileReader::new();
    reader.set_path(fixture("mol3.pse").to_str().unwrap());

    let molecules = reader.read_molecules().expect("read .pse molecules");
    assert_eq!(molecules.len(), 1, "expected one molecule object");
    let mol = &molecules[0];

    // The fixture is: ALA/1 N(0,0,0 b20) CA(1.5,0,0 b21); GLY/2 C(3,1.4,0 b22),
    // chain A, one N-CA bond.
    assert_eq!(mol.atom_count(), 3);
    let atoms = mol.atoms();

    assert_eq!(atoms[0].name, "N");
    assert_eq!(atoms[0].element, "N");
    assert_eq!(atoms[0].chain_id, "A");
    assert_eq!(atoms[0].res_name, "ALA");
    assert_eq!(atoms[0].res_id, 1);
    assert!((atoms[0].position.x - 0.0).abs() < 1.0e-4);
    assert!((atoms[0].b_factor - 20.0).abs() < 1.0e-3);

    assert_eq!(atoms[1].name, "CA");
    assert_eq!(atoms[1].element, "C");
    assert_eq!(atoms[1].res_name, "ALA");
    assert!((atoms[1].position.x - 1.5).abs() < 1.0e-4);

    assert_eq!(atoms[2].name, "C");
    assert_eq!(atoms[2].res_name, "GLY");
    assert_eq!(atoms[2].res_id, 2);
    assert!((atoms[2].position.x - 3.0).abs() < 1.0e-4);
    assert!((atoms[2].position.y - 1.4).abs() < 1.0e-3);
    assert!((atoms[2].b_factor - 22.0).abs() < 1.0e-3);

    // The N-CA bond (atoms 0-1) round-tripped.
    assert_eq!(mol.bonds().len(), 1);
    let bond = &mol.bonds()[0];
    assert!(
        (bond.atom1 == 0 && bond.atom2 == 1) || (bond.atom1 == 1 && bond.atom2 == 0),
        "expected an N-CA bond"
    );
}

#[test]
fn extracts_a_full_protein_from_a_real_pse() {
    // A real PyMOL `.pse` of 1CRN (46-residue, 327-atom protein) — exercises the
    // ChemPy traversal at scale, well beyond the 3-atom case. Oracle = the
    // well-known facts of 1CRN.
    let mut reader = PseFileReader::new();
    reader.set_path(fixture("1crn.pse").to_str().unwrap());

    let molecules = reader.read_molecules().expect("read 1crn .pse");
    assert_eq!(molecules.len(), 1);
    let mol = &molecules[0];
    assert_eq!(mol.atom_count(), 327, "1CRN has 327 atoms");

    let atoms = mol.atoms();
    // First atom of 1CRN is THR 1 N.
    assert_eq!(atoms[0].name, "N");
    assert_eq!(atoms[0].res_name, "THR");
    assert_eq!(atoms[0].res_id, 1);
    // Every atom carries an element and lands somewhere finite.
    assert!(atoms.iter().all(|a| !a.element.is_empty()));
    assert!(atoms.iter().all(|a| a.position.x.is_finite()));
    // 1CRN is a single 46-residue chain.
    let max_res = atoms.iter().map(|a| a.res_id).max().unwrap();
    assert_eq!(max_res, 46, "1CRN spans residues 1..=46");
    // A protein has many bonds (not just a handful).
    assert!(mol.bonds().len() > 300, "too few bonds: {}", mol.bonds().len());
}
